import type { IdentitySnapshot, PairingStatus } from '../model/identity.types.ts';

/** Re-authentication evidence for a sensitive action (regenerating the code): the current recovery code, or an approval from another device. */
export type Evidence = { readonly type: 'code'; readonly code: string } | { readonly type: 'approval'; readonly requestId: string };

/** A new recovery code generated by the SERVER, not in effect until confirmed (QĐ-6). */
export interface BegunReplacement {
  readonly pendingId: string;
  /** The displayed code `XXXXX-XXXXX-...` (30 symbols); shown only once. */
  readonly code: string;
  readonly expiresAt: number;
}

/** A request asking for approval from another device (re-authentication): a short code to type on the other device and a matching number for the other device to choose correctly. */
export interface StepUpRequested {
  readonly requestId: string;
  readonly approvalCode: string;
  readonly number: number;
  readonly expiresAt: number;
}

/** A recovery attempt with a code has started: the replacement code is generated by the server and expires after 15 minutes. */
export interface RecoveryStarted {
  readonly attemptId: string;
  readonly code: string;
  readonly expiresAt: number;
}

/** A pairing request that was created by the new device. */
export interface LinkCreated {
  readonly requestId: string;
  readonly pairingCode: string;
  readonly number: number;
  readonly expiresAt: number;
}

/** What the approving device sees before choosing the matching number: the request kind, the device name (self-declared, unverified), the time, the three choices. */
export interface ApprovalPreview {
  readonly kind: 'link' | 'stepUp';
  readonly code: string;
  readonly deviceName: string | null;
  readonly createdAt: number;
  readonly options: readonly number[];
}

/** The result of answering with the matching number. */
export type AnswerOutcome = 'approved' | 'wrong';

/**
 * The gateway to the backend's identity API (the D of SOLID): the UI only knows this contract. Every method is asynchronous and throws
 * an `ApiError` with a code (docs/ux/error-codes.md); the session secret is attached to the header by the implementation.
 */
export interface IdentityGateway {
  /** Creates an identity with its first session; returns the session secret (no recovery code yet, it is created in a later step). */
  createIdentity(deviceName: string): Promise<string>;
  /** The snapshot of this device's identity (devices, activity, the unseen flag, whether there is a code yet). 401 means the session has ended. */
  snapshot(): Promise<IdentitySnapshot>;
  /** The owner opened the Security screen: turns off the 'unseen' flag. */
  markSeen(): Promise<void>;
  /** Revokes a device (no re-authentication needed). */
  revoke(deviceId: string): Promise<void>;
  /** Renames or clears the name of this very device. */
  rename(name: string): Promise<void>;
  /** Issues a replacement code (phase 1); if there is a current code `evidence` is needed. */
  beginReplacement(evidence?: Evidence): Promise<BegunReplacement>;
  /** Confirms the replacement code (phase 2): the new code takes effect, the old code stops being valid. */
  confirmReplacement(pendingId: string, code: string): Promise<void>;
  /** Asks for a re-authentication approval from another device. */
  requestStepUp(): Promise<StepUpRequested>;
  /** Starts recovery on a new device with a code; `sessionToken` is generated by this device itself. */
  startRecovery(code: string, attemptId: string, sessionToken: string, deviceName: string): Promise<RecoveryStarted>;
  /** Completes recovery with the replacement code: the session of `sessionToken` takes effect. */
  completeRecovery(attemptId: string, replacementCode: string): Promise<void>;
  /** A new device asks to be paired with a trusted device. */
  createLink(sessionToken: string, deviceName: string): Promise<LinkCreated>;
  /** The status of the pairing request (the new device asks repeatedly). */
  linkStatus(requestId: string, signal?: AbortSignal): Promise<PairingStatus>;
  /** The approving device types the code (pairing or re-authentication) and previews; a wrong code throws `INVALID_PAIRING_CODE`/`INVALID_APPROVAL_CODE`. */
  preview(code: string): Promise<ApprovalPreview>;
  /** Answers the request with the matching number; a wrong choice denies that request for good. */
  answer(preview: ApprovalPreview, number: number): Promise<AnswerOutcome>;
  /** Actively denies. */
  deny(preview: ApprovalPreview): Promise<void>;
}
